[CmdletBinding()]
param(
    [switch]$Compile,
    [switch]$RunHardwareCompatibility,
    [switch]$ConfirmHardwareCompatibility,
    [switch]$RequireCurrentTag
)
$ErrorActionPreference='Stop'
$repo=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'))
$failures=[System.Collections.Generic.List[string]]::new()
$checks=[System.Collections.Generic.List[string]]::new()
function Pass([string]$Message){$checks.Add($Message);Write-Host "PASS  $Message" -ForegroundColor Green}
function Fail([string]$Message){$failures.Add($Message);Write-Host "FAIL  $Message" -ForegroundColor Red}
function Invoke-Git([string[]]$Arguments){$out=& git -C $repo @Arguments 2>&1;if($LASTEXITCODE -ne 0){throw "git $($Arguments -join ' ') failed ($LASTEXITCODE): $out"};return @($out)}
function Need-Text([string]$Relative,[string]$Pattern){$file=Join-Path $repo $Relative;if(!(Test-Path -LiteralPath $file)){Fail "Arquivo ausente: $Relative";return};$text=Get-Content -LiteralPath $file -Raw;if($text -notmatch $Pattern){Fail "Conteudo inconsistente em $Relative"}}
$versionPath=Join-Path $repo 'VERSION';$version=''
if(Test-Path $versionPath){$version=(Get-Content $versionPath -Raw).Trim();$semver='^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-(?:alpha|beta|rc)\.(0|[1-9]\d*))?$';if($version -match $semver){Pass "VERSION obedece SemVer: $version"}else{Fail "VERSION invalido: '$version'"}}else{Fail 'VERSION ausente'}
if($version){Need-Text 'CHANGELOG.md' ("(?m)^## \["+[regex]::Escape($version)+'\]') ;Need-Text 'VERSION_HISTORY.md' ([regex]::Escape($version));Need-Text 'RELEASE_NOTES.md' ([regex]::Escape('v'+$version));Need-Text 'docs/VERSIONING.md' 'Semantic Versioning|SemVer'}
$branch=(Invoke-Git @('branch','--show-current')|Select-Object -First 1).Trim();if($branch){Pass "Branch atual: $branch"}else{Fail 'HEAD sem branch'}
$commitCount=[int]((Invoke-Git @('rev-list','--count','HEAD')|Select-Object -First 1).Trim());if($commitCount -gt 0){Pass "Historico alcancavel: $commitCount commits"}else{Fail 'Historico Git vazio'}
$tags=@(Invoke-Git @('tag','--list'));$tagRegex='^v(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-(?:alpha|beta|rc)\.(0|[1-9]\d*))?$';foreach($tag in $tags){if(!$tag){continue};if($tag -notmatch $tagRegex){Fail "Tag fora do padrao: $tag";continue};$type=(Invoke-Git @('cat-file','-t',$tag)|Select-Object -First 1).Trim();if($type -ne 'tag'){Fail "Tag precisa ser anotada: $tag"}}
if($tags.Count -eq 0){if($RequireCurrentTag){Fail 'Nenhuma tag encontrada'}else{Write-Host 'INFO  Ainda sem tag; valide antes de criar v< VERSION >.' -ForegroundColor Cyan}}
if($RequireCurrentTag -and $version){$current='v'+$version;if($tags -notcontains $current){Fail "Tag requerida ausente: $current"}else{$tagCommit=(Invoke-Git @('rev-list','-n','1',$current)|Select-Object -First 1).Trim();$head=(Invoke-Git @('rev-parse','HEAD')|Select-Object -First 1).Trim();if($tagCommit -ne $head){Fail "Tag $current nao aponta para HEAD"}else{Pass "Tag anotada $current aponta para HEAD"}}}
$fsck=& git -C $repo fsck --full --strict 2>&1;if($LASTEXITCODE -eq 0){Pass 'git fsck --full --strict sem erros'}else{Fail "git fsck encontrou erro: $fsck"}
$tracked=@(Invoke-Git @('ls-files'));$trackedNormalized=@($tracked|ForEach-Object{$_.Replace('\\','/')});$manifestPath=Join-Path $repo 'copy-manifest.csv';if(Test-Path $manifestPath){$manifest=Import-Csv $manifestPath;$manifestOk=$true;$manifestChecked=0;foreach($row in $manifest){if($row.Identical -ne 'True' -or $row.SourceSHA256 -ne $row.CopySHA256){$manifestOk=$false;Fail 'Manifesto tem linha que nao declara copias identicas';break};$workspacePath=[string]$row.WorkspaceCopy;$rootPrefix=$repo.TrimEnd('\')+'\';if($workspacePath.StartsWith($rootPrefix,[StringComparison]::OrdinalIgnoreCase)){$rel=$workspacePath.Substring($rootPrefix.Length).Replace('\','/');if($trackedNormalized -contains $rel){$copy=Join-Path $repo $rel;if(!(Test-Path -LiteralPath $copy)){Fail "Arquivo rastreado ausente: $rel";$manifestOk=$false;break};$hash=(Get-FileHash -LiteralPath $copy -Algorithm SHA256).Hash;if($hash -ne $row.CopySHA256){Fail "SHA256 divergente no manifesto para $rel";$manifestOk=$false;break};$manifestChecked++}}};if($manifestOk){Pass "Manifesto consistente; $manifestChecked arquivos rastreados conferidos"}}else{Fail 'copy-manifest.csv ausente'}
$tooLarge=@();foreach($rel in $tracked){$f=Join-Path $repo $rel;if(Test-Path -LiteralPath $f -PathType Leaf){$item=Get-Item -LiteralPath $f;if($item.Length -ge 100MB){$tooLarge+=$rel}}};if($tooLarge.Count){Fail "Arquivos excedem 100 MiB: $($tooLarge -join ', ')"}else{Pass 'Arquivos rastreados abaixo de 100 MiB'}
if($Compile){$vs='C:\Program Files (x86)\Microsoft Visual Studio\18\BuildTools\Common7\Tools\VsDevCmd.bat';$fxc='C:\Program Files (x86)\Windows Kits\10\bin\10.0.26100.0\x64\fxc.exe';if(!(Test-Path $vs) -or !(Test-Path $fxc)){Fail 'Build Tools/FXC documentados nao encontrados; compilacao nao foi executada'}else{$temp=Join-Path ([IO.Path]::GetTempPath()) ('NEXO-Version-Compile-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $temp|Out-Null;foreach($phase in @('phase2-prototype','phase3-optimization')){$src=Join-Path $repo ("phases\$phase\source");$dst=Join-Path $temp $phase;New-Item -ItemType Directory -Path $dst|Out-Null;Copy-Item -LiteralPath (Join-Path $src 'build.ps1') -Destination $dst;Copy-Item -LiteralPath (Join-Path $src 'nexo_dual_gpu.cpp') -Destination $dst;Copy-Item -LiteralPath (Join-Path $src 'compute.hlsl') -Destination $dst;try{& (Join-Path $dst 'build.ps1')|Out-Host; if($LASTEXITCODE -and $LASTEXITCODE -ne 0){throw "Exit code $LASTEXITCODE"};if((Test-Path (Join-Path $dst 'nexo_dual_gpu.exe')) -and (Test-Path (Join-Path $dst 'compute.cso'))){Pass "Build isolado concluido: $phase"}else{throw 'outputs ausentes'}}catch{Fail "Build falhou em $phase; artefatos temporarios: $temp; $($_.Exception.Message)"}};Write-Host "INFO  Artefatos temporarios preservados em $temp" -ForegroundColor Cyan}}
if($RunHardwareCompatibility){if(!$ConfirmHardwareCompatibility){Fail 'Execucao em GPU requer -ConfirmHardwareCompatibility';}else{$pidFile='E:\NEXO-DUAL-GPU\phase4-monitoring\monitor.pid';$monitorActive=$false;if(Test-Path $pidFile){$monitorId=0;[void][int]::TryParse((Get-Content $pidFile -Raw).Trim(),[ref]$monitorId);if($monitorId -gt 0 -and (Get-Process -Id $monitorId -ErrorAction SilentlyContinue)){$monitorActive=$true}};if($monitorActive){Fail "Prova de GPU recusada: campanha da Fase 4 ativa (PID $monitorId); nao iniciar carga concorrente"}else{$diag=Join-Path $repo 'phases\phase1-diagnostic\artifacts\gpus-dxgi-d3d12.exe';if(!(Test-Path $diag)){Fail 'Executavel local de diagnostico DXGI/D3D12 ausente; nao foi compilado'}else{$entry=@(Import-Csv (Join-Path $repo 'copy-manifest.csv')|Where-Object{$_.WorkspaceCopy -ieq $diag}|Select-Object -First 1);if(!$entry -or (Get-FileHash -LiteralPath $diag -Algorithm SHA256).Hash -ne $entry[0].CopySHA256){Fail 'Executavel DXGI/D3D12 nao confere com o manifesto SHA256'}else{$diagOut=& $diag 2>&1|Out-String;Write-Output $diagOut;$gpu970=$diagOut -match '(?im)^Adapter\s+\d+: NVIDIA GeForce GTX 970$';$gpu750=$diagOut -match '(?im)^Adapter\s+\d+: NVIDIA GeForce GTX 750 Ti$';$devices=@([regex]::Matches($diagOut,'D3D12CreateDevice\(min FL11_0\)\s+HRESULT=0x00000000\s+OK')).Count;$shared=@([regex]::Matches($diagOut,'OpenSharedHandle heap on peer GPU\s+HRESULT=0x00000000\s+OK')).Count;if($LASTEXITCODE -eq 0 -and $gpu970 -and $gpu750 -and $devices -ge 2 -and $shared -ge 2){Pass 'DXGI/D3D12 + abertura de recursos Cross-Adapter nas duas GPUs'}else{Fail "Probe hardware incompleto: exit=$LASTEXITCODE, GTX970=$gpu970, GTX750Ti=$gpu750, D3D12=$devices, sharedHandles=$shared"}}}}}}
if($failures.Count){Write-Host "`n$($failures.Count) falha(s); $($checks.Count) verificacao(oes) passaram." -ForegroundColor Red;exit 1};Write-Host "`nValidacao concluida: $($checks.Count) verificacao(oes) passaram." -ForegroundColor Green
